contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(c.getTimestamp(c.hashOperation(target, value, data, predecessor, salt)) == 0);
        require(delay >= c.getMinDelay());

        c.grantRole(c.PROPOSER_ROLE(), address(this));

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 tsBefore = c.getTimestamp(id);

        c.schedule(target, value, data, predecessor, salt, delay);
        uint256 tsScheduled = c.getTimestamp(id);
        bool pendingAfterSchedule = c.isOperationPending(id);

        c.cancel(id);
        uint256 tsAfterCancel = c.getTimestamp(id);
        bool isOpAfterCancel = c.isOperation(id);

        assert(tsBefore == 0 && tsScheduled == block.timestamp + delay && pendingAfterSchedule && tsAfterCancel == 0 && !isOpAfterCancel);
    }

    receive() external payable {}
}

