contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 salt, uint256 delay, bytes32 badSalt, uint256 smallDelay) public {
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        require(!c.hasRole(c.PROPOSER_ROLE(), address(0)), "unexpected");
        bool reverted;
        try c.schedule(address(this), 0, "", bytes32(0), badSalt, smallDelay) { reverted = false; } catch { reverted = true; }
        assert(reverted == (smallDelay < c.getMinDelay()));
        if (reverted) {
            assert(c.getTimestamp(c.hashOperation(address(this), 0, "", bytes32(0), badSalt)) == 0);
        }
        c.schedule(address(this), 0, "", bytes32(0), salt, delay);
        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), salt);
        assert(c.getTimestamp(id) == block.timestamp + delay && c.isOperation(id) && c.isOperationPending(id) && !c.isOperationDone(id) && !c.isOperationReady(id));
    }
    receive() external payable {}
}

