contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public {
        // Grant ourselves the proposer role (we hold TIMELOCK_ADMIN_ROLE as deployer).
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 minDelayBefore = c.getMinDelay();
        uint256 tsBefore = c.getTimestamp(id);

        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 tsAfter = c.getTimestamp(id);
        assert(
            (delay >= minDelayBefore) == !reverted &&
            tsBefore == 0 &&
            (
                reverted
                    ? tsAfter == 0 && !c.isOperation(id)
                    : tsAfter == block.timestamp + delay &&
                      c.isOperation(id) &&
                      !c.isOperationReady(id) &&
                      c.isOperationPending(id)
            )
        );
    }

    receive() external payable {}
}

