contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 extra) public payable {
        // deployer (this contract) holds TIMELOCK_ADMIN_ROLE, so it can grant PROPOSER_ROLE to itself
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        uint256 delay = c.getMinDelay() + extra;
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 ts = c.getTimestamp(id);
        bool dupReverted;
        c.schedule(target, value, data, predecessor, salt, delay);
        // the duplicate call must revert (kept as a separate top-level try via a fresh identical call
        // is not allowed nested; instead assert on reachability of the double-schedule revert below)
        try c.schedule(target, value, data, predecessor, salt, delay) { dupReverted = false; } catch { dupReverted = true; }
        assert(ts == block.timestamp + delay && dupReverted && c.isOperation(id));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 extra) public payable {
        require(extra < 1e18, "delay too large");
        require(value == 0, "no value");
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        uint256 delay = c.getMinDelay() + extra;
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(c.isOperation(id), "not scheduled");
        c.cancel(id);
        assert(!c.isOperation(id) && c.getTimestamp(id) == 0);
    }
    receive() external payable {}
}
